    <script>
        function togglePassword() {
            const passwordInput = document.getElementById('passwordInput');
            const eyeIcon = document.getElementById('eyeIcon');
            
            if (passwordInput.type === 'password') {
                passwordInput.type = 'text';
                eyeIcon.innerHTML = `<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21"></path>`;
            } else {
                passwordInput.type = 'password';
                eyeIcon.innerHTML = `<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"></path>`;
            }
        }

        let captchaCode = "";
        function generateCaptcha() {
            const canvas = document.getElementById('captchaCanvas');
            const ctx = canvas.getContext('2d');
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            captchaCode = Math.floor(1000 + Math.random() * 9000).toString();
            ctx.font = 'bold 20px monospace';
            ctx.fillStyle = '#334155'; 
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(captchaCode, canvas.width/2, canvas.height/2);
            for(let i = 0; i < 5; i++) {
                ctx.beginPath();
                ctx.moveTo(Math.random() * canvas.width, Math.random() * canvas.height);
                ctx.lineTo(Math.random() * canvas.width, Math.random() * canvas.height);
                ctx.strokeStyle = '#94a3b8';
                ctx.lineWidth = 1;
                ctx.stroke();
            }
        }

        window.onload = generateCaptcha;

        const forgotPasswordLink = document.getElementById('forgotPasswordLink');
        const passwordRecoveryPanel = document.getElementById('passwordRecoveryPanel');
        if (forgotPasswordLink && passwordRecoveryPanel) {
            forgotPasswordLink.addEventListener('click', function (event) {
                event.preventDefault();
                document.getElementById('loginForm').classList.add('hidden');
                document.getElementById('loginIntro')?.classList.add('hidden');
                passwordRecoveryPanel.classList.remove('hidden');
            });
        }

        document.getElementById('loginForm').addEventListener('submit', function(e) {
            const inputVal = document.getElementById('captchaInput').value;
            if(inputVal !== captchaCode) {
                e.preventDefault();
                document.getElementById('captchaError').classList.remove('hidden');
                generateCaptcha();
                document.getElementById('captchaInput').value = '';
                document.getElementById('captchaInput').focus();
            } else {
                document.getElementById('captchaError').classList.add('hidden');
            }
        });
    </script>
</body>
</html>
